static void vnt_configure ( struct ieee80211_hw * hw , unsigned int changed_flags , unsigned int * total_flags , u64 multicast ) { struct vnt_private * priv = hw -> priv ; u8 rx_mode = 0 ; * total_flags &= FIF_ALLMULTI | FIF_OTHER_BSS | FIF_BCN_PRBRESP_PROMISC ; VNSvInPortB ( priv -> PortOffset + MAC_REG_RCR , & rx_mode ) ; dev_dbg ( & priv -> pcid -> dev , "rx mode in = %x\n" , rx_mode ) ; if ( changed_flags & FIF_ALLMULTI ) { if ( * total_flags & FIF_ALLMULTI ) { cfs_time_t flags ; spin_lock_irqsave ( & priv -> lock , flags ) ; if ( priv -> mc_list_count > 2 ) { MACvSelectPage1 ( priv -> PortOffset ) ; VNSvOutPortD ( priv -> PortOffset + MAC_REG_MAR0 , 0xffffffff ) ; VNSvOutPortD ( priv -> PortOffset + MAC_REG_MAR0 + 4 , 0xffffffff ) ; MACvSelectPage0 ( priv -> PortOffset ) ; } else { MACvSelectPage1 ( priv -> PortOffset ) ; VNSvOutPortD ( priv -> PortOffset + MAC_REG_MAR0 , ( u32 ) multicast ) ; VNSvOutPortD ( priv -> PortOffset + MAC_REG_MAR0 + 4 , ( u32 ) ( multicast >> 32 ) ) ; MACvSelectPage0 ( priv -> PortOffset ) ; } spin_unlock_irqrestore ( & priv -> lock , flags ) ; rx_mode |= RCR_MULTICAST | RCR_BROADCAST ; } else { rx_mode &= ~ ( RCR_MULTICAST | RCR_BROADCAST ) ; } } if ( changed_flags & ( FIF_OTHER_BSS | FIF_BCN_PRBRESP_PROMISC ) ) { rx_mode |= RCR_MULTICAST | RCR_BROADCAST ; if ( * total_flags & ( FIF_OTHER_BSS | FIF_BCN_PRBRESP_PROMISC ) ) { rx_mode &= ~ RCR_BSSID ; } else { rx_mode |= RCR_BSSID ; } } VNSvOutPortB ( priv -> PortOffset + MAC_REG_RCR , rx_mode ) ; dev_dbg ( & priv -> pcid -> dev , "rx mode out= %x\n" , rx_mode ) ; } 